create table settings(key text primary key,value text);
create table texts(key text primary key,id jsonb,en jsonb);
create table finishes(key text primary key,nama text,nama_en text,hex text,extra int default 0,urutan int default 0);
create table categories(slug text primary key,nama text,nama_en text,single text,single_en text,urutan int default 0,tampil boolean default true);
create table products(id text primary key,kategori text references categories(slug) on update cascade,harga int,finishes text[] default '{}',nama text,nama_en text,deskripsi text,deskripsi_en text,bahan text,bahan_en text,ukuran text,warna text,warna_en text,foto text[] default '{}',unggulan boolean default false,tampil boolean default true,urutan int default 0);
do $$ declare t text; begin foreach t in array array['settings','texts','finishes','categories','products'] loop
execute format('alter table %I enable row level security',t);
execute format('create policy "baca" on %I for select using (true)',t);
execute format('create policy "tulis" on %I for all to authenticated using (true) with check (true)',t);
end loop; end $$;
insert into storage.buckets(id,name,public) values('foto','foto',true) on conflict do nothing;
create policy "foto baca" on storage.objects for select using (bucket_id='foto');
create policy "foto tulis" on storage.objects for all to authenticated using (bucket_id='foto') with check (bucket_id='foto');
