insert into texts values ($q$nav_home$q$,$q$"Beranda"$q$::jsonb,$q$"Home"$q$::jsonb),($q$nav_products$q$,$q$"Produk"$q$::jsonb,$q$"Products"$q$::jsonb),($q$nav_about$q$,$q$"Tentang Kami"$q$::jsonb,$q$"About Us"$q$::jsonb),($q$nav_contact$q$,$q$"Kontak"$q$::jsonb,$q$"Contact"$q$::jsonb),($q$hero_eyebrow$q$,$q$"Luxury • Custom • Classic & Modern"$q$::jsonb,$q$"Luxury • Custom • Classic & Modern"$q$::jsonb),($q$hero_h1$q$,$q$"Wujudkan Rumah Impian, Satu Karya Jati Sekaligus"$q$::jsonb,$q$"Bring Your Dream Home to Life, One Teak Piece at a Time"$q$::jsonb),($q$hero_p$q$,$q$"Mebel kayu jati grade A buatan tangan pengrajin Jepara. Klasik, modern, hingga custom, siap untuk rumah, cafe, resto, dan villa."$q$::jsonb,$q$"Grade A teak furniture handmade by Jepara craftsmen. Classic, modern or custom, ready for homes, cafes, restaurants and villas."$q$::jsonb),($q$btn_catalog$q$,$q$"Lihat Katalog"$q$::jsonb,$q$"View Catalogue"$q$::jsonb),($q$btn_wa$q$,$q$"Tanya via WhatsApp"$q$::jsonb,$q$"Ask on WhatsApp"$q$::jsonb),($q$about_eyebrow$q$,$q$"Furnishing your dreams"$q$::jsonb,$q$"Furnishing your dreams"$q$::jsonb),($q$about_h$q$,$q$"Kayu Jati Pilihan, Dikerjakan dengan Hati"$q$::jsonb,$q$"Select Teak, Crafted with Heart"$q$::jsonb),($q$about_p$q$,$q$"Lini Rumah Jepara menghadirkan mebel jati berkualitas dari Jepara, kota ukir yang terkenal dengan keahlian kayunya. Setiap produk dibuat satu per satu agar tahan dipakai bertahun-tahun."$q$::jsonb,$q$"Lini Rumah Jepara brings you quality teak furniture from Jepara, the carving town known for its woodcraft. Each piece is made one at a time so it lasts for years."$q$::jsonb),($q$about_c1$q$,$q$"Kayu jati grade A pilihan, kering oven dan tahan lama"$q$::jsonb,$q$"Selected grade A teak, kiln-dried and long-lasting"$q$::jsonb),($q$about_c2$q$,$q$"Dikerjakan tangan oleh pengrajin berpengalaman di Jepara"$q$::jsonb,$q$"Handmade by experienced craftsmen in Jepara"$q$::jsonb),($q$about_c3$q$,$q$"Bisa custom ukuran, desain, dan finishing (walnut, impra, natural, marmer)"$q$::jsonb,$q$"Custom size, design and finish (walnut, impra, natural, marble)"$q$::jsonb),($q$about_more$q$,$q$"Kenali kami lebih dekat"$q$::jsonb,$q$"Get to know us"$q$::jsonb),($q$quotes$q$,$q$[["The details are not the details. They make the design.", "Charles Eames", "Desainer furnitur legendaris"], ["Design is not just what it looks like and feels like. Design is how it works.", "Steve Jobs", "Penemu & pendiri Apple"], ["Have nothing in your houses that you do not know to be useful, or believe to be beautiful.", "William Morris", "Desainer & pengrajin, pelopor gerakan Arts and Crafts"]]$q$::jsonb,$q$[["The details are not the details. They make the design.", "Charles Eames", "Legendary furniture designer"], ["Design is not just what it looks like and feels like. Design is how it works.", "Steve Jobs", "Co-founder of Apple"], ["Have nothing in your houses that you do not know to be useful, or believe to be beautiful.", "William Morris", "Designer & craftsman, a leader of the Arts and Crafts movement"]]$q$::jsonb),($q$mq1$q$,$q$["Kursi", "Sofa", "Tempat Tidur", "Lemari & Buffet"]$q$::jsonb,$q$["Chairs", "Sofas", "Beds", "Cabinets & Buffets"]$q$::jsonb),($q$mq2$q$,$q$["Kayu Jati", "Kombinasi Marmer", "Anyaman Rotan", "Custom"]$q$::jsonb,$q$["Teak Wood", "Marble Combination", "Rattan Weave", "Custom"]$q$::jsonb),($q$band$q$,$q$["Kayu Jati Grade A", "Luxury", "Custom", "Classic & Modern"]$q$::jsonb,$q$["Grade A Teak", "Luxury", "Custom", "Classic & Modern"]$q$::jsonb),($q$rooms_eyebrow$q$,$q$"Room Select"$q$::jsonb,$q$"Room Select"$q$::jsonb),($q$rooms_h$q$,$q$"Pilih Ruang, Pilih Karaktermu"$q$::jsonb,$q$"Pick a Room, Pick Your Character"$q$::jsonb),($q$rooms_p$q$,$q$"Klik ruangan, lalu pilih furnitur favoritmu. Lihat bagaimana setiap karya jati menghidupkan ruangan."$q$::jsonb,$q$"Tap a room, then choose your favourite piece. See how each teak creation brings a space to life."$q$::jsonb),($q$room_names$q$,$q${"tamu": "Ruang Tamu", "makan": "Ruang Makan", "kamar": "Kamar Tidur", "teras": "Teras & Santai"}$q$::jsonb,$q${"tamu": "Living Room", "makan": "Dining Room", "kamar": "Bedroom", "teras": "Patio & Lounge"}$q$::jsonb),($q$room_tags$q$,$q${"tamu": "Sambut tamu dengan kehangatan jati", "makan": "Meja makan yang mengundang cerita", "kamar": "Istirahat tenang di pelukan kayu", "teras": "Sudut bersantai untuk sore yang panjang"}$q$::jsonb,$q${"tamu": "Welcome guests with the warmth of teak", "makan": "A dining table that invites stories", "kamar": "Quiet rest, held in wood", "teras": "A corner for long afternoons"}$q$::jsonb),($q$pick$q$,$q$"Pilih Furnitur"$q$::jsonb,$q$"Choose a Piece"$q$::jsonb),($q$picked$q$,$q$"DIPILIH"$q$::jsonb,$q$"SELECTED"$q$::jsonb),($q$prev$q$,$q$"Sebelumnya"$q$::jsonb,$q$"Previous"$q$::jsonb),($q$next$q$,$q$"Berikutnya"$q$::jsonb,$q$"Next"$q$::jsonb),($q$s_mat$q$,$q$"Bahan"$q$::jsonb,$q$"Material"$q$::jsonb),($q$s_size$q$,$q$"Ukuran"$q$::jsonb,$q$"Size"$q$::jsonb),($q$s_color$q$,$q$"Warna"$q$::jsonb,$q$"Colour"$q$::jsonb),($q$s_price$q$,$q$"Harga"$q$::jsonb,$q$"Price"$q$::jsonb),($q$s_finish$q$,$q$"Finishing"$q$::jsonb,$q$"Finish"$q$::jsonb),($q$finish$q$,$q$"Pilihan Finishing"$q$::jsonb,$q$"Finish Options"$q$::jsonb),($q$ask_wa$q$,$q$"Tanya via WhatsApp"$q$::jsonb,$q$"Ask on WhatsApp"$q$::jsonb),($q$ask_custom$q$,$q$"Tanya Custom"$q$::jsonb,$q$"Ask for Custom"$q$::jsonb),($q$view_detail$q$,$q$"Lihat Detail"$q$::jsonb,$q$"View Details"$q$::jsonb),($q$feat_eyebrow$q$,$q$"Koleksi Pilihan"$q$::jsonb,$q$"Featured Collection"$q$::jsonb),($q$feat_h$q$,$q$"Produk Unggulan"$q$::jsonb,$q$"Featured Products"$q$::jsonb),($q$all_products$q$,$q$"Lihat semua produk"$q$::jsonb,$q$"View all products"$q$::jsonb),($q$proj_eyebrow$q$,$q$"Ready for project"$q$::jsonb,$q$"Ready for project"$q$::jsonb),($q$proj_h$q$,$q$"Untuk Cafe, Resto & Villa"$q$::jsonb,$q$"For Cafes, Restaurants & Villas"$q$::jsonb),($q$proj_p$q$,$q$"Dari satu set kursi hingga ratusan unit, kami mengerjakan pengadaan furni